-- YUGASTRA catalogue: 5 collections and 20 watches, every field including Hindi. Safe to re-run (upserts by slug).
-- Run after schema.sql and hindi-update.sql. Price ₹3,999, compare-at ₹5,999.
alter table collections add column if not exists tagline_hi text, add column if not exists headline_hi text, add column if not exists description_hi text, add column if not exists story_hi text, add column if not exists meaning_hi text;
alter table products add column if not exists tagline_hi text, add column if not exists description_hi text, add column if not exists long_description_hi text, add column if not exists stock_mode text default 'in_stock', add column if not exists video text;
insert into collections(slug,name,theme,tagline,headline,description,variants_label,sanskrit,meaning,story,dial_color,sort,tagline_hi,headline_hi,description_hi,meaning_hi,story_hi,active) values ('dhruv','DHRUV','dhruv','The realm of stillness','Be the fixed point.','The still point of the turning sky. A compass of raised gold upon deepest navy, for those who keep their bearing.','3 watches','ध्रुव','Dhruva · unmoving · the pole star','Dhruva was a boy who sat in stillness until the heavens gave him a place that never moves. Every sailor and sage since has steered by that star. We asked what a fixed point would look like on the wrist, and drew a compass rose in raised gold, with the seven stars of the Saptarishi leading the eye to north. The dial is navy, the hour just after sunset when the first star appears. DHRUV is the realm of stillness: for those who stay true to their direction while the world turns around them. It is the first watch of the first age, and the one that never loses its bearing.','Navy',1,'स्थिरता का लोक','अचल बिंदु बनिए।','घूमते आकाश का स्थिर बिंदु। गहनतम नील पर उभरा स्वर्णिम दिशासूचक, उनके लिए जो अपनी दिशा थामे रखते हैं।','ध्रुव · अचल · ध्रुव तारा','ध्रुव एक बालक था, जो तब तक स्थिर बैठा रहा जब तक आकाश ने उसे वह स्थान नहीं दे दिया जो कभी नहीं डिगता। तब से प्रत्येक नाविक और मनीषी ने उसी तारे के सहारे दिशा पाई है। हमने पूछा कि कलाई पर एक अचल बिंदु कैसा दिखेगा, और उभरे स्वर्ण में एक दिशासूचक रचा, जिसमें सप्तर्षि के सात तारे दृष्टि को उत्तर की ओर ले जाते हैं। डायल नीलवर्ण है, सूर्यास्त के ठीक पश्चात की वह बेला जब पहला तारा प्रकट होता है। ध्रुव स्थिरता का लोक है: उनके लिए जो संसार के घूमते रहने पर भी अपनी दिशा के प्रति सच्चे रहते हैं। यह प्रथम युग की प्रथम घड़ी है, और वह जो अपनी दिशा कभी नहीं खोती।',true)
 on conflict (slug) do update set name=excluded.name,theme=excluded.theme,tagline=excluded.tagline,headline=excluded.headline,description=excluded.description,variants_label=excluded.variants_label,sanskrit=excluded.sanskrit,meaning=excluded.meaning,story=excluded.story,dial_color=excluded.dial_color,sort=excluded.sort,tagline_hi=excluded.tagline_hi,headline_hi=excluded.headline_hi,description_hi=excluded.description_hi,meaning_hi=excluded.meaning_hi,story_hi=excluded.story_hi;
insert into collections(slug,name,theme,tagline,headline,description,variants_label,sanskrit,meaning,story,dial_color,sort,tagline_hi,headline_hi,description_hi,meaning_hi,story_hi,active) values ('surya','SURYA','surya','The realm of light','Carry your own light.','Twelve rays of burnished gold upon black, in homage to the sun that wakes the world.','5 watches','सूर्य','Surya · the sun, giver of light','The Vedas open their hymns to Surya, the sun that wakes the world. Tradition counts twelve Adityas, twelve forms of the sun, one for every month. We gave the dial twelve raised rays, six straight for steady light and six wavy for heat, alternating around a gold disc. We set it on black because the sun in the real sky is a single source of light in a very large dark. SURYA is the realm of light: for those who do not wait to be lit, and who carry their own radiance into every room.','Black',2,'प्रकाश का लोक','अपना प्रकाश स्वयं धारण कीजिए।','श्याम पर तपे हुए स्वर्ण की बारह किरणें, उस सूर्य को अर्पण जो संसार को जगाता है।','सूर्य · तेज के दाता','वेद अपने सूक्तों का आरंभ सूर्य से करते हैं, उस सूर्य से जो संसार को जगाता है। परंपरा बारह आदित्य गिनती है, सूर्य के बारह स्वरूप, प्रत्येक मास के लिए एक। हमने डायल को बारह उभरी किरणें दीं, छह सीधी स्थिर प्रकाश के लिए और छह लहरदार ऊष्मा के लिए, जो एक स्वर्ण मंडल के चारों ओर बारी-बारी से सजती हैं। हमने इसे श्याम पर स्थापित किया, क्योंकि वास्तविक आकाश में सूर्य एक विशाल अंधकार में प्रकाश का अकेला स्रोत है। सूर्य प्रकाश का लोक है: उनके लिए जो प्रज्वलित किए जाने की प्रतीक्षा नहीं करते, और अपना तेज हर सभा में साथ लिए चलते हैं।',true)
 on conflict (slug) do update set name=excluded.name,theme=excluded.theme,tagline=excluded.tagline,headline=excluded.headline,description=excluded.description,variants_label=excluded.variants_label,sanskrit=excluded.sanskrit,meaning=excluded.meaning,story=excluded.story,dial_color=excluded.dial_color,sort=excluded.sort,tagline_hi=excluded.tagline_hi,headline_hi=excluded.headline_hi,description_hi=excluded.description_hi,meaning_hi=excluded.meaning_hi,story_hi=excluded.story_hi;
insert into collections(slug,name,theme,tagline,headline,description,variants_label,sanskrit,meaning,story,dial_color,sort,tagline_hi,headline_hi,description_hi,meaning_hi,story_hi,active) values ('naksh','NAKSH','naksh','The realm of destiny','Some things are written.','Twenty-seven stars, one for each night of the moon''s long procession, impressed upon a ground of ritual maroon.','4 watches','नक्श','Naksh · a mark, an imprint · echoing the 27 nakshatras','The ancient sky-watchers divided the moon''s path into twenty-seven nakshatras, one resting place for each night of its journey. We set all twenty-seven as raised eight-point stars in an unbroken ring, beginning with Ashwini at the top, around a quiet gold hub. Naksh means a mark, an imprint, and that is the intention: a pattern that stays. The dial is maroon, the colour of ritual, festival and long evenings. NAKSH is the realm of destiny: for those who believe some things are written, and who wear the proof.','Maroon',3,'नियति का लोक','कुछ बातें लिखी जा चुकी हैं।','सत्ताईस तारे, चंद्रमा की लंबी यात्रा की प्रत्येक रात्रि के लिए एक, अनुष्ठान के गहरे रक्तवर्ण पर अंकित।','नक्श · एक चिह्न, एक छाप · सत्ताईस नक्षत्रों की प्रतिध्वनि','प्राचीन आकाश-द्रष्टाओं ने चंद्रमा के पथ को सत्ताईस नक्षत्रों में विभाजित किया, उसकी यात्रा की प्रत्येक रात्रि के लिए एक विश्राम-स्थल। हमने सभी सत्ताईस को उभरे अष्टकोणीय तारों के रूप में एक अविच्छिन्न वलय में स्थापित किया, शीर्ष पर अश्विनी से आरंभ करते हुए, एक शांत स्वर्ण केंद्र के चारों ओर। नक्श का अर्थ है एक चिह्न, एक छाप, और यही हमारा अभिप्राय है: एक आकृति जो बनी रहे। डायल गहरे रक्तवर्ण का है, अनुष्ठान, उत्सव और लंबी संध्याओं का रंग। नक्श नियति का लोक है: उनके लिए जो मानते हैं कि कुछ बातें लिखी जा चुकी हैं, और जो उसका प्रमाण धारण करते हैं।',true)
 on conflict (slug) do update set name=excluded.name,theme=excluded.theme,tagline=excluded.tagline,headline=excluded.headline,description=excluded.description,variants_label=excluded.variants_label,sanskrit=excluded.sanskrit,meaning=excluded.meaning,story=excluded.story,dial_color=excluded.dial_color,sort=excluded.sort,tagline_hi=excluded.tagline_hi,headline_hi=excluded.headline_hi,description_hi=excluded.description_hi,meaning_hi=excluded.meaning_hi,story_hi=excluded.story_hi;
insert into collections(slug,name,theme,tagline,headline,description,variants_label,sanskrit,meaning,story,dial_color,sort,tagline_hi,headline_hi,description_hi,meaning_hi,story_hi,active) values ('vyom','VYOM','vyom','The realm of space','Keep looking up.','Nine luminaries in their ordained orbits, suspended in the green hush of the open sky.','4 watches','व्योम','Vyom · the sky, space, the open ether','Vyom is the open sky, the ether that holds everything. The Vedic astronomers followed nine bodies, the Navagraha: the sun, the moon, the five visible planets and the two lunar nodes. We drew them as nine gold beads on orbit rings around a striated sphere, so that the whole sky reads as an instrument on the wrist. The dial is deep green, the sky seen through leaves after rain. VYOM is the realm of space: for those who still look up, and who understand that depth is a form of luxury.','Dark green',4,'अंतरिक्ष का लोक','ऊपर देखते रहिए।','नौ ज्योतिर्मय पिंड अपनी नियत कक्षाओं में, खुले आकाश की हरित निस्तब्धता में स्थित।','व्योम · आकाश, अंतरिक्ष, अनंत आकाश-तत्त्व','व्योम खुला आकाश है, वह तत्त्व जो सब कुछ धारण करता है। वैदिक खगोलविदों ने नौ पिंडों का अनुसरण किया, नवग्रह: सूर्य, चंद्र, पाँच दृश्य ग्रह और दो चंद्र-बिंदु। हमने उन्हें एक धारीदार गोले के चारों ओर कक्षा-वलयों पर नौ स्वर्ण मणियों के रूप में रचा, ताकि संपूर्ण आकाश कलाई पर एक यंत्र की भाँति पढ़ा जा सके। डायल गहरा हरित है, वर्षा के पश्चात पत्तों के बीच से दिखता आकाश। व्योम अंतरिक्ष का लोक है: उनके लिए जो आज भी ऊपर देखते हैं, और जानते हैं कि गहराई स्वयं एक प्रकार की विलासिता है।',true)
 on conflict (slug) do update set name=excluded.name,theme=excluded.theme,tagline=excluded.tagline,headline=excluded.headline,description=excluded.description,variants_label=excluded.variants_label,sanskrit=excluded.sanskrit,meaning=excluded.meaning,story=excluded.story,dial_color=excluded.dial_color,sort=excluded.sort,tagline_hi=excluded.tagline_hi,headline_hi=excluded.headline_hi,description_hi=excluded.description_hi,meaning_hi=excluded.meaning_hi,story_hi=excluded.story_hi;
insert into collections(slug,name,theme,tagline,headline,description,variants_label,sanskrit,meaning,story,dial_color,sort,tagline_hi,headline_hi,description_hi,meaning_hi,story_hi,active) values ('soma','SOMA','soma','The realm of rhythm','Calm, in cycles.','Thirty lunar days circle a crescent of silver, upon graphite as quiet as moonlit stone.','4 watches','सोम','Soma · the moon, and the luminous drink of the Vedas','The Rigveda gives an entire book to Soma, the moon and the luminous drink of the gods. The lunar month is counted in thirty tithis, fifteen as the moon grows and fifteen as it fades. We set thirty dots in a ring, fifteen bright and fifteen dark, around a hammered silver crescent. The dial is graphite, moonlit stone, and the detail is silver only, because the moon has no gold. SOMA is the realm of rhythm: for those who find calm in cycles, and trust that everything returns in its own time.','Graphite',5,'लय का लोक','चक्रों में शांति।','तीस चांद्र तिथियाँ एक रजत अर्धचंद्र को घेरे हुए, चाँदनी में नहाए पत्थर-से शांत धूसर पटल पर।','सोम · चंद्रमा, और वेदों का दीप्तिमान पेय','ऋग्वेद एक संपूर्ण मंडल सोम को अर्पित करता है, चंद्रमा को और देवताओं के दीप्तिमान पेय को। चांद्र मास की गणना तीस तिथियों में होती है, पंद्रह जब चंद्रमा बढ़ता है और पंद्रह जब घटता है। हमने तीस बिंदु एक वलय में स्थापित किए, पंद्रह उज्ज्वल और पंद्रह श्याम, एक गढ़े हुए रजत अर्धचंद्र के चारों ओर। डायल धूसर है, चाँदनी में नहाया पत्थर, और अलंकरण केवल रजत का है, क्योंकि चंद्रमा के पास स्वर्ण नहीं होता। सोम लय का लोक है: उनके लिए जो चक्रों में शांति पाते हैं, और विश्वास रखते हैं कि सब कुछ अपने समय पर लौट आता है।',true)
 on conflict (slug) do update set name=excluded.name,theme=excluded.theme,tagline=excluded.tagline,headline=excluded.headline,description=excluded.description,variants_label=excluded.variants_label,sanskrit=excluded.sanskrit,meaning=excluded.meaning,story=excluded.story,dial_color=excluded.dial_color,sort=excluded.sort,tagline_hi=excluded.tagline_hi,headline_hi=excluded.headline_hi,description_hi=excluded.description_hi,meaning_hi=excluded.meaning_hi,story_hi=excluded.story_hi;
insert into products(slug,name,sku,tagline,description,long_description,case_color,strap_color,weight_g,price,compare_price,stock,edition_total,edition_sold,featured,sort,seo_title,seo_description,tagline_hi,description_hi,long_description_hi,collection_id,features,specs,images,stock_mode,active) values ('dhruv-night','Dhruv Night','YG-DHR-BK-BK','Constancy, in black.','Stillness at its darkest. Black case, black strap, an embossed navy compass dial. Japanese quartz.','Stillness at its darkest. A black case holds a deep navy dial, where a compass rose and the seven sages stand in raised gold, as quiet and as certain as the star they follow. A black tonneau case, 44 × 52 mm and 17 mm deep, with a deep and even finish. The black silicone strap is soft, light and moulded to sit flush against the case. Within is an accurate Japanese quartz movement. Dhruv Night belongs to Dhruv, one realm of the Yugastra sky: a timeless piece, made to be kept and not replaced.','Black','Black',85,3999,5999,50,0,0,true,1,'Dhruv Night · Dhruv Collection | YUGASTRA','Constancy, in black. Dhruv Night: black case, black strap, an embossed navy compass dial. Japanese quartz, 1-year warranty. From YUGASTRA, the weapon of timelessness. ₹5,999.','स्थिरता, श्याम में।','गहनतम अंधकार में स्थिरता। श्याम आवरण, श्याम पट्टा, उभरे हुए नील डायल पर दिशासूचक। जापानी क्वार्ट्ज़।','गहनतम अंधकार में स्थिरता। श्याम टोन्यू आवरण, 44 × 52 मिमी और 17 मिमी मोटा, गहरी और समरूप सज्जा के साथ। श्याम सिलिकॉन पट्टा कोमल और हल्का है, और आवरण से सटकर बैठने के लिए ढला है। भीतर एक सटीक जापानी क्वार्ट्ज़ गति-तंत्र है। Dhruv Night युगास्त्र के आकाश के एक लोक की कृति है: कालातीत, सहेजने के लिए रची गई, बदले जाने के लिए नहीं।',(select id from collections where slug='dhruv'),'["Embossed navy dial with raised gold detail","Japanese quartz movement","Black tonneau case, Black silicone strap","44 × 52 mm, 17 mm deep","1-year warranty","Water resistant to 5 ATM (50 m)"]'::jsonb,'{"Movement":"Japanese quartz","Case":"Black, tonneau, 44 × 52 mm, 17 mm deep","Strap":"Black silicone","Dial":"Embossed navy dial","Weight":"Approx. 85 g","Warranty":"1 year","Water resistance":"5 ATM (50 m)","Strap width":"22 mm","Fits wrists":"14–20 cm"}'::jsonb,'["https://5n9sx3cugrn0sd1z.public.blob.vercel-storage.com/yugastra/products/YG-DHR-BK-BK-1.png","https://5n9sx3cugrn0sd1z.public.blob.vercel-storage.com/yugastra/products/YG-DHR-BK-BK-2.png","https://5n9sx3cugrn0sd1z.public.blob.vercel-storage.com/yugastra/products/YG-DHR-BK-BK-3.png","https://5n9sx3cugrn0sd1z.public.blob.vercel-storage.com/yugastra/products/YG-DHR-BK-BK-4.png","https://5n9sx3cugrn0sd1z.public.blob.vercel-storage.com/yugastra/products/YG-DHR-BK-BK-5.png","https://5n9sx3cugrn0sd1z.public.blob.vercel-storage.com/yugastra/products/YG-DHR-BK-BK-6.png"]'::jsonb,'in_stock',true)
