anese quartz","Case":"Silver, tonneau, 44 × 52 mm, 17 mm deep","Strap":"Black silicone","Dial":"Embossed black dial","Weight":"Approx. 85 g","Warranty":"1 year","Water resistance":"5 ATM (50 m)","Strap width":"22 mm","Fits wrists":"14–20 cm"}'::jsonb,'[]'::jsonb,'in_stock',true)
