ranty","Water resistant to 5 ATM (50 m)"]'::jsonb,'{"Movement":"Japanese quartz","Case":"Black, tonneau, 44 × 52 mm, 17 mm deep","Strap":"Black silicone","Dial":"Embossed maroon dial","Weight":"Approx. 85 g","Warranty":"1 year","Water resistance":"5 ATM (50 m)","Strap width":"22 mm","Fits wrists":"14–20 cm"}'::jsonb,'["https://5n9sx3cugrn0sd1z.public.blob.vercel-storage.com/yugastra/products/YG-NAK-BK-BK-1.png","https://5n9sx3cugrn0sd1z.public.blob.vercel-storage.com/yugastra/products/YG-NAK-BK-BK-2.png","https://5n9sx3cugrn0sd1z.public.blob.vercel-storage.com/yugastra/products/YG-NAK-BK-BK-3.png","https://5n9sx3cugrn0sd1z.public.blob.vercel-storage.com/yugastra/products/YG-NAK-BK-BK-4.png","https://5n9sx3cugrn0sd1z.public.blob.vercel-storage.com/yugastra/products/YG-NAK-BK-BK-5.png","https://5n9sx3cugrn0sd1z.public.blob.vercel-storage.com/yugastra/products/YG-NAK-BK-BK-6.png"]'::jsonb,'in_stock',true)
