mbossed deep green dial with nine graha","Japanese quartz movement","Gold tonneau case, Green silicone strap","44 × 52 mm, 17 mm deep","1-year warranty","Water resistant to 5 ATM (50 m)"]'::jsonb,'{"Movement":"Japanese quartz","Case":"Gold, tonneau, 44 × 52 mm, 17 mm deep","Strap":"Green silicone","Dial":"Embossed dark green dial","Weight":"Approx. 85 g","Warranty":"1 year","Water resistance":"5 ATM (50 m)","Strap width":"22 mm","Fits wrists":"14–20 cm"}'::jsonb,'["https://5n9sx3cugrn0sd1z.public.blob.vercel-storage.com/yugastra/products/YG-VYO-GD-GN-1.png","https://5n9sx3cugrn0sd1z.public.blob.vercel-storage.com/yugastra/products/YG-VYO-GD-GN-2.png","https://5n9sx3cugrn0sd1z.public.blob.vercel-storage.com/yugastra/products/YG-VYO-GD-GN-3.png","https://5n9sx3cugrn0sd1z.public.blob.vercel-storage.com/yugastra/products/YG-VYO-GD-GN-4.png","https://5n9sx3cugrn0sd1z.public.blob.vercel-storage.com/yugastra/products/YG-VYO-GD-GN-5.png","https://5n9sx3cugrn0sd1z.public.blob.vercel-storage.com/yugastra/products/YG-VYO-GD-GN-6.png"]'::jsonb,'in_stock',true)
