insert into products(slug,name,sku,tagline,description,long_description,case_color,strap_color,weight_g,price,compare_price,stock,edition_total,edition_sold,featured,sort,seo_title,seo_description,tagline_hi,description_hi,long_description_hi,collection_id,features,specs,images,stock_mode,active) values ('soma-new-moon','Soma New Moon','YG-SOM-BK-BK','The quiet before the light returns.','All black, with the crescent barely there. Black case, black strap, an embossed graphite dial with a silver crescent. Japanese quartz.','All black, with the crescent barely there. It is the new moon, when nothing is shown and everything is promised. A black tonneau case, 44 × 52 mm and 17 mm deep, with a deep and even finish. The black silicone strap is soft, light and moulded to sit flush against the case. Within is an accurate Japanese quartz movement. Soma New Moon belongs to Soma, one realm of the Yugastra sky: a timeless piece, made to be kept and not replaced.','Black','Black',85,3999,5999,50,0,0,false,19,'Soma New Moon · Soma Collection | YUGASTRA','The quiet before the light returns. Soma New Moon: black case, black strap, an embossed graphite dial with a silver crescent. Japanese quartz, 1-year warranty. From YUGASTRA, the weapon of timelessness. ₹5,999.','प्रकाश के लौटने से पूर्व की निस्तब्धता।','संपूर्ण श्याम, जिसमें अर्धचंद्र बस हल्का-सा झलकता है। श्याम आवरण, श्याम पट्टा, रजत अर्धचंद्र वाला उभरा हुआ धूसर डायल। जापानी क्वार्ट्ज़।','संपूर्ण श्याम, जिसमें अर्धचंद्र बस हल्का-सा झलकता है। श्याम टोन्यू आवरण, 44 × 52 मिमी और 17 मिमी मोटा, गहरी और समरूप सज्जा के साथ। श्याम सिलिकॉन पट्टा कोमल और हल्का है, और आवरण से सटकर बैठने के लिए ढला है। भीतर एक सटीक जापानी क्वार्ट्ज़ गति-तंत्र है। Soma New Moon युगास्त्र के आकाश के एक लोक की कृति है: कालातीत, सहेजने के लिए रची गई, बदले जाने के लिए नहीं।',(select id from collections where slug='soma'),'["Embossed graphite dial with a silver crescent","Japanese quartz movement","Black tonneau case, Black silicone strap","44 × 52 mm, 17 mm deep","1-year warranty","Water resistant to 5 ATM (50 m)"]'::jsonb,'{"Movement":"Japanese quartz","Case":"Black, tonneau, 44 × 52 mm, 17 mm deep","Strap":"Black silicone","Dial":"Embossed graphite dial","Weight":"Approx. 85 g","Warranty":"1 year","Water resistance":"5 ATM (50 m)","Strap width":"22 mm","Fits wrists":"14–20 cm"}'::jsonb,'["https://5n9sx3cugrn0sd1z.public.blob.vercel-storage.com/yugastra/products/YG-SOM-BK-BK-1.png","https://5n9sx3cugrn0sd1z.public.blob.vercel-storage.com/yugastra/products/YG-SOM-BK-BK-2.png","https://5n9sx3cugrn0sd1z.public.blob.vercel-storage.com/yugastra/products/YG-SOM-BK-BK-3.png","https://5n9sx3cugrn0sd1z.public.blob.vercel-storage.com/yugastra/products/YG-SOM-BK-BK-4.png","https://5n9sx3cugrn0sd1z.public.blob.vercel-storage.com/yugastra/products/YG-SOM-BK-BK-5.png","https://5n9sx3cugrn0sd1z.public.blob.vercel-storage.com/yugastra/products/YG-SOM-BK-BK-6.png"]'::jsonb,'in_stock',true)
 on conflict (slug) do update set name=excluded.name,sku=excluded.sku,tagline=excluded.tagline,description=excluded.description,long_description=excluded.long_description,case_color=excluded.case_color,strap_color=excluded.strap_color,weight_g=excluded.weight_g,price=excluded.price,compare_price=excluded.compare_price,stock=excluded.stock,edition_total=excluded.edition_total,edition_sold=excluded.edition_sold,featured=excluded.featured,sort=excluded.sort,seo_title=excluded.seo_title,seo_description=excluded.seo_description,tagline_hi=excluded.tagline_hi,description_hi=excluded.description_hi,long_description_hi=excluded.long_description_hi,collection_id=excluded.collection_id,features=excluded.features,specs=excluded.specs,images=excluded.images;
insert into products(slug,name,sku,tagline,description,long_description,case_color,strap_color,weight_g,price,compare_price,stock,edition_total,edition_sold,featured,sort,seo_title,seo_description,tagline_hi,description_hi,long_description_hi,collection_id,features,specs,images,stock_mode,active) values ('soma-moonlight','Soma Moonlight','YG-SOM-BK-WH','Moonlight, in monochrome.','A black case set off by a white strap. Black case, white strap, an embossed graphite dial with a silver crescent. Japanese quartz.','A black case set off by a white strap. Stark and graceful, like a moonlit path in a still garden. A black tonneau case, 44 × 52 mm and 17 mm deep, with a deep and even finish. The white silicone strap is soft, light and moulded to sit flush against the case. Within is an accurate Japanese quartz movement. Soma Moonlight belongs to Soma, one realm of the Yugastra sky: a timeless piece, made to be kept and not replaced.','Black','White',85,3999,5999,50,0,0,false,20,'Soma Moonlight · Soma Collection | YUGASTRA','Moonlight, in monochrome. Soma Moonlight: black case, white strap, an embossed graphite dial with a silver crescent. Japanese quartz, 1-year warranty. From YUGASTRA, the weapon of timelessness. ₹5,999.','चाँदनी, एकवर्णी में।','श्वेत पट्टे से निखरा हुआ श्याम आवरण। श्याम आवरण, श्वेत पट्टा, रजत अर्धचंद्र वाला उभरा हुआ धूसर डायल। जापानी क्वार्ट्ज़।','श्वेत पट्टे से निखरा हुआ श्याम आवरण। श्याम टोन्यू आवरण, 44 × 52 मिमी और 17 मिमी मोटा, गहरी और समरूप सज्जा के साथ। श्वेत सिलिकॉन पट्टा कोमल और हल्का है, और आवरण से सटकर बैठने के लिए ढला है। भीतर एक सटीक जापानी क्वार्ट्ज़ गति-तंत्र है। Soma Moonlight युगास्त्र के आकाश के एक लोक की कृति है: कालातीत, सहेजने के लिए रची गई, बदले जाने के लिए नहीं।',(select id from collections where slug='soma'),'["Embossed graphite dial with a silver crescent","Japanese quartz movement","Black tonneau case, White silicone strap","44 × 52 mm, 17 mm deep","1-year warranty","Water resistant to 5 ATM (50 m)"]'::jsonb,'{"Movement":"Japanese quartz","Case":"Black, tonneau, 44 × 52 mm, 17 mm deep","Strap":"White silicone","Dial":"Embossed graphite dial","Weight":"Approx. 85 g","Warranty":"1 year","Water resistance":"5 ATM (50 m)","Strap width":"22 mm","Fits wrists":"14–20 cm"}'::jsonb,'["https://5n9sx3cugrn0sd1z.public.blob.vercel-storage.com/yugastra/products/YG-SOM-BK-WH-1.png","https://5n9sx3cugrn0sd1z.public.blob.vercel-storage.com/yugastra/products/YG-SOM-BK-WH-2.png","https://5n9sx3cugrn0sd1z.public.blob.vercel-storage.com/yugastra/products/YG-SOM-BK-WH-3.png","https://5n9sx3cugrn0sd1z.public.blob.vercel-storage.com/yugastra/products/YG-SOM-BK-WH-4.png","https://5n9sx3cugrn0sd1z.public.blob.vercel-storage.com/yugastra/products/YG-SOM-BK-WH-5.png","https://5n9sx3cugrn0sd1z.public.blob.vercel-storage.com/yugastra/products/YG-SOM-BK-WH-6.png"]'::jsonb,'in_stock',true)
